-- NEWCAR-1: BYD joins Proton / Perodua / Toyota as a new-car brand (owner, 2026-10-18).
-- One migration (one API freeze): widen the two brand CHECKs, then load the
-- BYD price list from the owner's file (byd_malaysia_models_2026.json, "2026-10").
--
-- On the road without insurance, Peninsular. Deliberately left out:
--   East Malaysia prices: the file calls them "approximate, based on dealer
--     listings". A zone with no price shows "ask"; an estimate must never read
--     as the official price, so price_sabah_sarawak stays NULL.
--   Range for M6 and Sealion 7: the file gives NEDC only (M6) or an
--     "approximate" WLTP (Sealion 7). range_km elsewhere is WLTP (e.MAS rows),
--     and NEDC reads ~15% higher, so mixing them would mislead. Add once confirmed.
--   Airbags: stated only where the file says so (Atto 2, Atto 3).
-- Dolphin is not in the file, so it is not listed.

alter table public.profiles drop constraint if exists profiles_new_car_brand_check;
alter table public.profiles add constraint profiles_new_car_brand_check
  check (new_car_brand is null or new_car_brand = any (array['Proton','Perodua','Toyota','BYD']));

alter table public.new_car_models drop constraint if exists new_car_models_brand_check;
alter table public.new_car_models add constraint new_car_models_brand_check
  check (brand = any (array['Proton','Perodua','Toyota','BYD']));

insert into public.new_car_models
  (brand, model, variant, body_type, fuel_type, transmission, price_peninsular, price_sabah_sarawak, effective_from, source_url, sort_order, specs)
